// Explicit env: PLAYWRIGHT_MODULE, GITDASH_TEST_ORIGIN, GITDASH_TEST_OUTPUT, GITDASH_TEST_FIXTURE.
const assert=require('node:assert/strict'),fs=require('node:fs/promises');const {chromium}=require(process.env.PLAYWRIGHT_MODULE);
(async()=>{const fixture=JSON.parse(await fs.readFile(process.env.GITDASH_TEST_FIXTURE,'utf8')),origin=process.env.GITDASH_TEST_ORIGIN,output=process.env.GITDASH_TEST_OUTPUT;assert.ok(origin&&output);await fs.mkdir(output,{recursive:true});const browser=await chromium.launch({headless:true}),page=await browser.newPage({viewport:{width:1440,height:1000},timezoneId:'Asia/Tokyo'}),errors=[],passed=[];page.on('pageerror',e=>errors.push(e.message));page.setDefaultTimeout(20000);
 const url=tab=>`${origin}/project?path=${encodeURIComponent(fixture.path)}&tab=${tab}&range=current`;
 const download=async(scope,name)=>{const event=page.waitForEvent('download');await scope.getByRole('button',{name,exact:true}).click();return fs.readFile(await(await event).path());};
 const capture=async(scope,name)=>{await scope.screenshot({path:`${output}/${name}.png`,style:'.agent-timeline-sidebar, .skip-link { visibility:hidden !important; }'});await page.setViewportSize({width:390,height:844});await scope.screenshot({path:`${output}/${name}-mobile.png`,style:'.agent-timeline-sidebar, .skip-link { visibility:hidden !important; }'});assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1),`${name} mobile overflow`);await page.setViewportSize({width:1440,height:1000});};
 try{
  await page.goto(url('files'));const sizes=page.locator('.tree-sizes');await sizes.locator('summary').click();await sizes.getByLabel('容量調査のrevision',{exact:true}).fill('main');await sizes.getByRole('button',{name:'版の容量を取得',exact:true}).click();await sizes.locator('.tree-sizes-file-table tbody tr').first().waitFor();assert.equal(await sizes.locator('.tree-sizes-file-table tbody tr').count(),6);assert.ok((await sizes.locator('.tree-sizes-file-table tbody tr').first().innerText()).includes('src/large.bin'));assert.ok((await sizes.locator('.tree-sizes-file-table tr').filter({hasText:'vendor'}).innerText()).includes('サイズ未取得'));
  await sizes.locator('#tree-sizes-min-bytes').fill('8192');assert.equal(await sizes.locator('.tree-sizes-file-table tbody tr').count(),1);assert.ok((await download(sizes,'絞り込み結果をCSV保存')).toString().includes('8192'));await sizes.locator('#tree-sizes-min-bytes').fill('0');await sizes.locator('#tree-sizes-min-bytes-error').waitFor();await sizes.locator('#tree-sizes-min-bytes').fill('');await sizes.getByLabel('容量一覧の種類フィルター',{exact:true}).selectOption('gitlink');assert.equal(await sizes.locator('.tree-sizes-file-table tbody tr').count(),1);await sizes.getByLabel('容量一覧の種類フィルター',{exact:true}).selectOption('all');
  await sizes.locator('.tree-sizes-chart-row').filter({hasText:'src'}).click();assert.equal(await sizes.locator('.tree-sizes-file-table tbody tr').count(),2);assert.ok((await sizes.locator('.tree-sizes-breadcrumbs').innerText()).includes('src'));const sizeCsv=(await download(sizes,'絞り込み結果をCSV保存')).toString();assert.ok(sizeCsv.includes('src/large.bin')&&sizeCsv.includes('src/small.txt')&&!sizeCsv.includes('docs/copy.txt'));await sizes.getByRole('button',{name:'ルート',exact:true}).click();await sizes.getByLabel('容量一覧の並び順',{exact:true}).selectOption('path');await sizes.getByLabel('容量一覧の並び方向',{exact:true}).selectOption('ascending');assert.ok((await sizes.locator('.tree-sizes-largest').innerText()).includes('src/large.bin'));await capture(sizes,'tree-sizes');await sizes.locator('summary').click();
  passed.push('Pinned per-path Git object sizes including duplicate blobs, unknown gitlink sizes, directory totals/drilldown, minimum/type filters and invalid minimum, filtered CSV');
  // Conflict index inspection follows; no resolutions or Git writes are requested by the UI.
  await page.goto(url('info'));const refs=page.locator('.commit-containment');await refs.locator('summary').click();await refs.getByLabel('コミット含有参照を調べるrevision',{exact:true}).fill(fixture.base);await refs.getByRole('button',{name:'このコミットを調査',exact:true}).click();await page.waitForFunction(()=>document.querySelectorAll('.commit-containment-table tbody tr').length===5);
  await refs.getByLabel('参照の種類で絞り込み',{exact:true}).selectOption('remote');assert.equal(await refs.locator('.commit-containment-table tbody tr').count(),1);assert.ok((await refs.locator('.commit-containment-table').innerText()).includes('refs/remotes/origin/main'));await refs.getByLabel('参照の種類で絞り込み',{exact:true}).selectOption('tag');assert.equal(await refs.locator('.commit-containment-table tbody tr').count(),2);await refs.getByLabel('取得済み参照を検索',{exact:true}).fill('release');assert.equal(await refs.locator('.commit-containment-table tbody tr').count(),1);
  const refsCsv=(await download(refs,'一致する参照をCSV保存')).toString();assert.ok(refsCsv.includes('refs/tags/release')&&refsCsv.includes(fixture.main)&&!refsCsv.includes('refs/tags/base-tag'));await refs.getByRole('button',{name:'コミットを表示',exact:true}).click();await refs.locator('.commit-containment-detail').getByText('Main changes conflict',{exact:true}).waitFor();await capture(refs,'commit-containment');
  const href=await refs.getByRole('link',{name:'比較条件を入力',exact:true}).getAttribute('href');assert.ok(href.includes(fixture.base)&&href.includes(fixture.main));let compareRequests=0;page.on('request',request=>{if(new URL(request.url()).pathname==='/api/repo/compare')compareRequests++;});await refs.getByRole('link',{name:'比較条件を入力',exact:true}).click();await page.waitForFunction(expected=>document.querySelector('[aria-label="比較元 base のコミットハッシュまたはGit ref"]')?.value===expected,fixture.base);assert.equal(await page.getByLabel('比較先 target のコミットハッシュまたはGit ref',{exact:true}).inputValue(),fixture.main);assert.equal(compareRequests,0);
  passed.push('Containing local/remote/tag refs, exact type/name filtering, pinned target commit detail, pinned comparison prefill without execution, matching CSV');
  await page.goto(url('files'));
  const conflicts=page.locator('.conflict-inspector');await conflicts.locator('summary').click();await conflicts.getByRole('button',{name:'競合一覧を取得',exact:true}).click();await conflicts.locator('.conflict-inspector-table tbody tr').first().waitFor();assert.equal(await conflicts.locator('.conflict-inspector-table tbody tr').count(),1);const conflictCsv=(await download(conflicts,'一覧をCSV保存')).toString();assert.ok(conflictCsv.includes('conflict.txt'));
  await conflicts.getByLabel('調べる競合ファイル',{exact:true}).selectOption('conflict.txt');const stages=conflicts.getByRole('group',{name:'競合stageを選択'});for(const [name,text] of [['BASE','base version\n'],['OURS','ours version\n'],['THEIRS','theirs version\n']]){await stages.getByRole('button',{name:new RegExp(`^${name}`)}).click();await page.waitForFunction(expected=>document.querySelector('.conflict-inspector-text')?.textContent===expected,text);assert.equal((await download(conflicts,'完全なblobを保存')).toString(),text);}
  await conflicts.getByRole('button',{name:'OURS / THEIRSを比較',exact:true}).click();await conflicts.locator('.conflict-inspector-comparison').waitFor();const patch=await conflicts.locator('.conflict-inspector-comparison').innerText();assert.ok(patch.includes('ours version')&&patch.includes('theirs version'));await capture(conflicts,'conflict-inspector');
  passed.push('Unmerged index inventory, BASE/OURS/THEIRS independent previews and exact-byte downloads, read-only variant comparison, inventory CSV');
  const delayed=async pattern=>{let seen,release,done;const captured=new Promise(resolve=>seen=resolve),gate=new Promise(resolve=>release=resolve),finished=new Promise(resolve=>done=resolve);await page.route(pattern,async route=>{try{const response=await route.fetch();seen();await gate;try{await route.fulfill({response});}catch{/* Aborted requests must not publish results. */}}finally{done();}});return{captured:()=>Promise.race([captured,new Promise((_,reject)=>setTimeout(()=>reject(new Error('Delayed route was not requested')),20000).unref())]),release,finished};};
  const sizeDelay=await delayed(/\/api\/repo\/tree-sizes\?/);await sizes.locator('summary').click();await sizes.getByLabel('容量調査のrevision',{exact:true}).fill('main');await sizes.getByRole('button',{name:'版の容量を取得',exact:true}).click();await sizeDelay.captured();await sizes.getByLabel('容量調査のrevision',{exact:true}).fill('feature');sizeDelay.release();await sizeDelay.finished;await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));assert.equal(await sizes.locator('.tree-sizes-file-table tbody tr').count(),0);await page.unroute(/\/api\/repo\/tree-sizes\?/);await sizes.getByRole('button',{name:'版の容量を取得',exact:true}).click();await page.waitForFunction(()=>document.querySelectorAll('.tree-sizes-file-table tbody tr').length===5);await sizes.locator('summary').click();
  const stageDelay=await delayed(/\/api\/repo\/conflict-stage\?/);await stages.getByRole('button',{name:/^BASE/}).click();await stageDelay.captured();await conflicts.getByRole('button',{name:'競合一覧を再取得',exact:true}).click();await conflicts.locator('.conflict-inspector-table tbody tr').first().waitFor();stageDelay.release();await stageDelay.finished;await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));assert.equal(await conflicts.locator('.conflict-inspector-preview').count(),0);await page.unroute(/\/api\/repo\/conflict-stage\?/);
  passed.push('Delayed tree-size results discarded after revision edit and delayed conflict-stage results discarded after inventory refresh');
  assert.deepEqual(errors,[]);await fs.writeFile(`${output}/result.json`,JSON.stringify({origin,fixture:fixture.path,passed,errors},null,2));console.log({passed,errors});
 }catch(e){console.error(e);console.error(await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,overflow:[...document.querySelectorAll('body *')].filter(e=>e.getBoundingClientRect().right>innerWidth+1).slice(-15).map(e=>({tag:e.tagName,cls:e.className,right:e.getBoundingClientRect().right,width:e.getBoundingClientRect().width}))})));await page.screenshot({path:`${output}/failure.png`});console.error((await page.locator('body').innerText()).slice(-3500));process.exitCode=1;}finally{await browser.close();}
})();
